// intent: Exercise UBJSON serialization of a large boolean vector forcing incremental growth of the vector sink window.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array();
        for (int i = 0; i < 40000; ++i) {
            j.push_back(i % 2 == 0);
        }
        std::vector<uint8_t> v = nlohmann::json::to_ubjson(j);
        std::cout << "UBJSON boolean array size: " << v.size() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
